target.css:
:root {
  --ink: #18233d;
  --paper: #fffdf7;
  --line: #d8d9e4;
  --muted: #68708a;
  --violet: #7058d8;
  --violet-soft: #eeeaff;
  --cyan: #20aabd;
  --mint: #dcf6ee;
  --amber: #e39a38;
}

.sample-card {
  box-sizing: border-box;
  width: 500px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px 18px 8px 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.sample-id {
  display: flex;
  align-items: center;
  gap: 10px;
}

.phoneme {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  color: var(--violet);
  background: var(--violet-soft);
  border-radius: 12px 12px 4px 12px;
  font-size: 14px;
  font-weight: 800;
}

.sample-id p {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.75px;
}

.sample-id h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1;
  letter-spacing: -0.35px;
}

.status {
  padding: 5px 8px;
  color: var(--cyan);
  background: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.signal-grid {
  display: grid;
  grid-template-columns: 1.65fr 1fr;
  gap: 12px;
  padding: 12px 0;
}

.waveform {
  margin: 0;
  padding: 11px 12px;
  background: var(--ink);
  border-radius: 12px 4px 12px 12px;
}

.waveform figcaption {
  display: flex;
  justify-content: space-between;
  color: var(--line);
  font-size: 11px;
  font-weight: 700;
}

.waveform figcaption strong {
  color: var(--amber);
  font-size: 11px;
}

.wave {
  display: flex;
  height: 67px;
  align-items: center;
  gap: 5px;
}

.wave span {
  width: 100%;
  background: var(--cyan);
  border-radius: 99px;
}

.wave span:nth-child(1) { height: 15px; }
.wave span:nth-child(2) { height: 31px; }
.wave span:nth-child(3) { height: 49px; background: var(--violet); }
.wave span:nth-child(4) { height: 23px; }
.wave span:nth-child(5) { height: 57px; background: var(--amber); }
.wave span:nth-child(6) { height: 39px; }
.wave span:nth-child(7) { height: 62px; background: var(--violet); }
.wave span:nth-child(8) { height: 29px; }
.wave span:nth-child(9) { height: 46px; }
.wave span:nth-child(10) { height: 20px; background: var(--amber); }
.wave span:nth-child(11) { height: 35px; }
.wave span:nth-child(12) { height: 13px; }

.metrics {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 3px 0;
}

.metric {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin: 0;
  padding: 8px 9px;
  background: var(--violet-soft);
  border-radius: 7px;
}

.metric:nth-child(2) {
  background: var(--mint);
}

.metric:nth-child(3) {
  background: var(--paper);
  border: 1px solid var(--line);
}

.metric span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.metric strong {
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.record-dot {
  width: 7px;
  height: 7px;
  background: var(--amber);
  border-radius: 50%;
}

.review-button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--violet);
  border: 0;
  border-radius: 7px 7px 2px 7px;
  font-size: 11px;
  font-weight: 800;
}

.review-button span {
  margin-left: 5px;
  color: var(--paper);
  font-size: 14px;
}

